update app_private.outreach_templates set parts=null,
subject='your loads, covered by FMCSA-verified carriers — free',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Hi,</p><p>I run LoadBoot, a free load board where every carrier is FMCSA-verified before they can bid &mdash; authority, insurance, even the truck's VIN matched against its insurance certificate. I found {NAME} on the broker register.</p><p>Two ways to try it &mdash; pick the lazier one:</p><p><b>Zero effort:</b> add <b>loads@loadboot.com</b> to the load list you already email your carriers. Your loads land on our board automatically &mdash; free, no per-post fee, and your contact info stays on every load. Nothing about how you work changes.</p><p><b>Two minutes:</b> <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d1&oc={OC}" style="color:#0883F7">create a free broker account</a> and post directly &mdash; post, cover, rate con and invoice, one screen.</p><p>Reply with any question &mdash; a real person answers, not a sales queue.</p><p style="margin:24px 0 0">Riley<br>Broker Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d1&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='broker' and day=1;

update app_private.outreach_templates set parts=null,
subject='the 5-minute check that stops double-brokering',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Freight fraud is the worst it has ever been, and most of it walks in through a rushed carrier setup. Five checks, five minutes, before you tender to anyone new:</p><p>1. Call the phone number on the carrier's <b>FMCSA record</b> &mdash; not the one in their email signature.<br>2. Get the COI from the insurance <b>agent</b> directly, then call the agent back on the agency's public number.<br>3. Match the truck's <b>VIN</b> to the scheduled autos on that COI.<br>4. Authority under 6 months + a brand-new factoring NOA + pressure to move today = slow down.<br>5. If the dispatcher &ldquo;can't do a quick call&rdquo; about pickup details &mdash; walk.</p><p>On LoadBoot every one of those runs <b>automatically at booking</b> &mdash; a carrier that fails cannot bid on your load. <a href="https://loadboot.com/compliance.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="color:#0883F7">Here is how the verification works</a> &mdash; and <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="color:#0883F7">posting is free, permanently</a>.</p><p style="margin:24px 0 0">Riley<br>Broker Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='broker' and day=2;

update app_private.outreach_templates set parts=null,
subject='"where''s my truck" should be a dead question',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Every check call is a minute nobody gets back &mdash; times every load, every day.</p><p>Two things you can do this week, with or without us: write <b>arrive/depart timestamps into your rate con as a requirement</b>, and give your shipper <b>one tracking link</b> instead of a phone chain.</p><p>On LoadBoot each load carries live GPS with geofenced arrive/depart stamps &mdash; your shipper's &ldquo;where is my freight&rdquo; answers itself, and detention arguments end with a shared clock instead of two phone stories.</p><p><a href="https://loadboot.com/gps-tracking.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="color:#0883F7">See how the tracking works</a> &middot; <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="color:#0883F7">post loads free</a>.</p><p style="margin:24px 0 0">Riley<br>Broker Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='broker' and day=3;

update app_private.outreach_templates set parts=null,
subject='pay the real detention claims, kill the fake ones',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Detention is only hard because both sides are guessing. Three lines to put in your next rate con: the <b>free time</b> (two hours is standard), the <b>$/hr after it</b>, and <b>which clock decides</b>. Then pay clean claims inside 48 hours &mdash; carriers remember who pays, and your hardest lanes get covered first.</p><p>With geofenced timestamps you pay the real claims fast and decline the fake ones with proof instead of a fight. <a href="https://loadboot.com/detention-pay-policy.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d4&oc={OC}" style="color:#0883F7">Here is the policy we use</a> &mdash; steal it even if you never use us.</p><p style="margin:24px 0 0">Riley<br>Broker Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d4&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='broker' and day=4;

update app_private.outreach_templates set parts=null,
subject='5:40pm Friday, freight on the dock',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Vetting is easy on Monday morning. It fails at 5:40pm on a Friday with freight on the dock and one truck available.</p><p>The playbook that saves that hour: <b>post early</b> with honest appointment windows; keep a <b>bench of five small carriers per lane</b> who answer their own phones; and when 12 pallets won't fill a 53', <b>price it as a partial</b> instead of paying for air.</p><p>On LoadBoot the vetting runs at booking, automatically &mdash; authority, insurance, safety record, VIN-to-COI. Your worst day gets vetted exactly like your best. <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d5&oc={OC}" style="color:#0883F7">Post your next load free</a>.</p><p style="margin:24px 0 0">Riley<br>Broker Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d5&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='broker' and day=5;

update app_private.outreach_templates set parts=null,
subject='one screen: post, cover, rate con, invoice',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Most brokerages run one system to post, another to track, a third for rate cons and a fourth for invoices &mdash; and re-key the same load into each. Time one load end-to-end this week: fifteen minutes of re-typing per load is normal, and it is pure margin.</p><p>LoadBoot does all four on one screen: post, cover with a verified carrier, send the rate con, settle. <a href="https://loadboot.com/payments-settlements.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d6&oc={OC}" style="color:#0883F7">Here is how the money side works</a> &middot; <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d6&oc={OC}" style="color:#0883F7">free to post, always</a>.</p><p style="margin:24px 0 0">Riley<br>Broker Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d6&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='broker' and day=6;

update app_private.outreach_templates set parts=null,
subject='last one from me',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>My last email &mdash; no more after this.</p><p>The short version: posting on LoadBoot is free forever, every carrier arrives FMCSA-verified with the truck's VIN matched to its insurance, and every load carries GPS proof. <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d7&oc={OC}" style="color:#0883F7">Two minutes to a free account</a> &mdash; or skip all of it and add <b>loads@loadboot.com</b> to your daily load blast; your freight reaches our carriers with zero change to how you work.</p><p>If none of that is useful, no hard feelings. The number below reaches me any hour if that ever changes.</p><p style="margin:24px 0 0">Riley<br>Broker Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d7&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='broker' and day=7;

