update app_private.outreach_templates set parts=null,
subject='what {STATE} lanes are paying this week',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Hi,</p><p>I run LoadBoot, a load board and dispatch platform. I found {NAME} on the FMCSA register, so forgive the cold email.</p><p>This week's all-in spot averages: dry van <b>${RATE_VAN}/mi</b>, reefer <b>${RATE_REEFER}/mi</b>, flatbed <b>${RATE_FLATBED}/mi</b>. <a href="https://loadboot.com/market-rates.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d1&oc={OC}" style="color:#0883F7">Your lanes are here</a> &mdash; free, no login.</p><p>One offer, no signup: <b>reply with your equipment and the two or three lanes you actually run</b>, and I will send you what those lanes are paying right now, plus matching loads as they come in. That is the whole pitch.</p><p style="margin:24px 0 0">Riley<br>Carrier Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d1&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:13px;color:#64748b;margin-top:10px">PD: &iquest;Prefieres espa&ntilde;ol? Responde en espa&ntilde;ol &mdash; contestamos igual.</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='carrier' and day=1;

update app_private.outreach_templates set parts=null,
subject='why detention money goes unpaid',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Brokers pay detention all the time. They just do not pay carriers who ask three days late with no times.</p><p>What gets paid: in/out times recorded at the gate, one timestamped photo, and the invoice sent the same day. That is nearly the whole trick.</p><p>The full playbook: <a href="https://loadboot.com/detention-pay-policy.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d2&oc={OC}" style="color:#0883F7">how to actually collect detention</a>.</p><p>And if a broker owes you detention right now, reply with what happened. I will tell you straight whether it is collectable.</p><p style="margin:24px 0 0">Riley<br>Carrier Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d2&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='carrier' and day=2;

update app_private.outreach_templates set parts=null,
subject='three lines in a rate con worth reading twice',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Almost every rate con has three lines that quietly move money from you to the broker: the free-time clause, the &ldquo;all-in&rdquo; wording, and whether pay terms start at POD <i>received</i> or POD <i>approved</i>.</p><p>I broke a real one down line by line: <a href="https://loadboot.com/how-to-read-a-rate-confirmation.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d3&oc={OC}" style="color:#0883F7">how to read a rate confirmation</a>.</p><p>Want a second pair of eyes on one of yours? Reply and attach it. Free, and I answer these myself.</p><p style="margin:24px 0 0">Riley<br>Carrier Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d3&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='carrier' and day=3;

update app_private.outreach_templates set parts=null,
subject='do you know your real cost per mile?',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Most owner-operators who tell me a load &ldquo;made money&rdquo; are guessing. Truck payment, insurance, maintenance, tires, permits, your own pay &mdash; the real number is usually higher than it feels.</p><p>I built a free calculator. Two minutes, no email, no signup: <a href="https://loadboot.com/cost-per-mile-calculator.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d4&oc={OC}" style="color:#0883F7">work out your cost per mile</a>.</p><p>Once you know your number, &ldquo;that's the market rate&rdquo; stops working on you.</p><p style="margin:24px 0 0">Riley<br>Carrier Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d4&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='carrier' and day=4;

update app_private.outreach_templates set parts=null,
subject='new authority? the first 90 days decide everything',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>If {NAME} is a newer authority: the first 90 days end more trucking companies than the next five years, and it is almost never the driving. It is the filings and the cash flow.</p><p>BOC-3, UCR, 2290, insurance actually showing on your FMCSA record, a factoring NOA to every broker &mdash; in the right order. I wrote it up: <a href="https://loadboot.com/how-to-get-loads-with-new-authority.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d5&oc={OC}" style="color:#0883F7">the first 90 days, step by step</a>.</p><p>And when you are ready for loads: <a href="https://loadboot.com/create-carrier-account.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d5&oc={OC}" style="color:#0883F7">a free LoadBoot account</a> gets your COI read by AI in minutes, your authority monitored, and lane matches sent to your inbox &mdash; so brokers see you verified before they ever call.</p><p>Stuck on any of it? Reply &mdash; a real person answers, usually within the hour.</p><p style="margin:24px 0 0">Riley<br>Carrier Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d5&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='carrier' and day=5;

update app_private.outreach_templates set parts=null,
subject='waiting 30 days for money you already earned',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Net-30 is how small carriers die with full order books. The load is delivered, the fuel is paid, and the money arrives next month.</p><p>If you factor, do it right &mdash; the NOA has to reach every broker you haul for, or the check goes to the wrong party and becomes your problem. Plain-English guide: <a href="https://loadboot.com/factoring-noa.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d6&oc={OC}" style="color:#0883F7">factoring and the NOA, done right</a>.</p><p>On LoadBoot, invoices and settlements live with the load, so nothing waits because paperwork got lost.</p><p style="margin:24px 0 0">Riley<br>Carrier Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d6&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='carrier' and day=6;

update app_private.outreach_templates set parts=null,
subject='last one from me',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>This is my last email &mdash; I do not chase people forever.</p><p>The short version: LoadBoot is a free load board with FMCSA-verified companies on both sides, live market rates, GPS tracking and invoicing in one place &mdash; run by people who answer their own phone, any hour. <a href="https://loadboot.com/create-carrier-account.html?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d7&oc={OC}" style="color:#0883F7">An account takes two minutes</a> &mdash; or just reply with your lanes and I will email you matches myself.</p><p>Good luck out there. It is a hard business, run by tough people.</p><p style="margin:24px 0 0">Riley<br>Carrier Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=carrier-d7&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='carrier' and day=7;

