update app_private.outreach_templates set parts=null,
subject='a freight-protection checklist for shippers',
html=$T$<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#1a1a1a;max-width:560px"><p>Hi,</p><p>I run LoadBoot, a direct-to-carrier shipping platform. I found {NAME} in the shipper register.</p><p>Whether or not you ever use us: we wrote a plain-English checklist on protecting freight from loss, damage and double-brokering fraud &mdash; checks that take minutes and regularly save five figures. <a href="https://loadboot.com/protect-freight-from-loss-damage-and-fraud.html?utm_source=email&utm_medium=outreach&utm_campaign=shipper-d1&oc={OC}" style="color:#0883F7">The checklist is here</a>, free, no signup.</p><p>And if you ever want lanes quoted direct to verified carriers with live GPS on every load, just reply &mdash; we read every message that lands here.</p><p style="margin:24px 0 0">Riley<br>Shipper Support, LoadBoot<br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=shipper-d1&oc={OC}" style="color:#0883F7">loadboot.com</a> &middot; +1 (469) 253-7575, any hour</p><p style="font-size:12px;color:#8a8a8a;margin-top:28px;border-top:1px solid #eeeeee;padding-top:12px">I found {NAME} on the public FMCSA register. If you would rather not hear from me, <a href="{UNSUB}" style="color:#8a8a8a">one click here</a> and I stop.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</p></div>$T$
where audience='shipper' and day=1;
